using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace Upsy.Flyout;

/// <summary>
/// The 16-DIP brand icon: the 16 px pixel art at 100 % scale, the 32 px small icon above it
/// (both generated by tools/gen_brand_icons.py).
/// </summary>
public sealed class BrandIcon : Image
{
    private static readonly BitmapSource Small = Load("upsy-16.png");
    private static readonly BitmapSource Large = Load("upsy-32.png");

    public BrandIcon()
    {
        Width = 16;
        Height = 16;
        Pick(1);
        Loaded += (_, _) => Pick(VisualTreeHelper.GetDpi(this).DpiScaleX);
    }

    protected override void OnDpiChanged(DpiScale oldDpi, DpiScale newDpi)
    {
        base.OnDpiChanged(oldDpi, newDpi);
        Pick(newDpi.DpiScaleX);
    }

    private void Pick(double scale)
    {
        var exact = scale <= 1;
        Source = exact ? Small : Large;
        RenderOptions.SetBitmapScalingMode(this, exact ? BitmapScalingMode.NearestNeighbor : BitmapScalingMode.HighQuality);
    }

    private static BitmapFrame Load(string name)
    {
        var frame = BitmapFrame.Create(new Uri($"pack://application:,,,/upsy;component/Assets/{name}"));
        frame.Freeze();
        return frame;
    }
}
